// Native unit tests for the portable core. The expected hashes come from
// hardware/meter-sakshi/samples/sample-log.csv, generated by the TypeScript evidence
// engine, so a passing run proves the firmware and the report agree byte for byte.
#include <unity.h>

#include <string>

#include "pulse_filter.h"
#include "record.h"
#include "sha256.h"

using namespace sakshi;

void setUp() {}
void tearDown() {}

void test_sha256_known_vectors() {
  TEST_ASSERT_EQUAL_STRING("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", sha256Hex("abc").c_str());
  TEST_ASSERT_EQUAL_STRING("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", sha256Hex("").c_str());
  // 56-byte message crosses the padding boundary.
  TEST_ASSERT_EQUAL_STRING("248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1",
                           sha256Hex("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq").c_str());
}

void test_minute_formatting() {
  char minute[18];
  formatMinute(29846550, minute);
  TEST_ASSERT_EQUAL_STRING("2026-09-30T18:30Z", minute);
  formatMinute(0, minute);
  TEST_ASSERT_EQUAL_STRING("1970-01-01T00:00Z", minute);
  char day[9];
  formatDay(29846550, day);
  TEST_ASSERT_EQUAL_STRING("20260930", day);
}

void test_chain_matches_typescript_engine() {
  const std::string genesis = genesisHash("MS-DEMO01", 3200);
  TEST_ASSERT_EQUAL_STRING("f9ff691e4d1194e59ce545631711600dcfeb74a08901b16ca8b10f3497f6e0a5", genesis.c_str());
  const Record first{29846550, 5, kBoot, 0};
  const std::string h1 = nextHash(genesis, first);
  TEST_ASSERT_EQUAL_STRING("10059c403f2f7711c6d389efd9a85a17232654dc102e2f9636b21000906624c9", h1.c_str());
  const Record second{29846551, 6, 0, 0};
  const std::string h2 = nextHash(h1, second);
  TEST_ASSERT_EQUAL_STRING("830c30e445595ac38b1c66a6c5f35983db864143e6ff17c88feacf1eb98b1165", h2.c_str());
  TEST_ASSERT_EQUAL_STRING("2026-09-30T18:31Z,6,0,830c30e445595ac38b1c66a6c5f35983db864143e6ff17c88feacf1eb98b1165",
                           csvLine(second, h2).c_str());
}

void test_pulse_filter() {
  PulseFilter filter(15000);
  TEST_ASSERT_TRUE(filter.accept(1000));
  TEST_ASSERT_FALSE(filter.accept(5000));   // chatter 4 ms later
  TEST_ASSERT_TRUE(filter.accept(20000));   // 19 ms after the accepted pulse
  TEST_ASSERT_EQUAL_UINT32(1, filter.rejected());
  PulseFilter wrap(15000);
  TEST_ASSERT_TRUE(wrap.accept(0xFFFFF000u));
  TEST_ASSERT_TRUE(wrap.accept(0x00003000u));  // 16 ms later across the 32-bit wrap
  TEST_ASSERT_EQUAL_UINT32(70312, maxSafeFilterUs(3200, 14.4f));
}

int main(int, char**) {
  UNITY_BEGIN();
  RUN_TEST(test_sha256_known_vectors);
  RUN_TEST(test_minute_formatting);
  RUN_TEST(test_chain_matches_typescript_engine);
  RUN_TEST(test_pulse_filter);
  return UNITY_END();
}
